// Package db wraps database/sql with a tiny dialect layer so the same SQL
// runs on SQLite (default) and PostgreSQL.
//
// Portability rules used by all queries in the code base:
//   - placeholders are written as "?" and rebound to $1.. for PostgreSQL
//   - only TEXT, INTEGER and BIGINT columns; booleans are 0/1 integers
//   - timestamps are unix seconds (BIGINT, UTC)
//   - identifiers are random hex strings generated by the application
package db

import (
	"context"
	"database/sql"
	"fmt"
	"strconv"
	"strings"

	_ "github.com/jackc/pgx/v5/stdlib"
	_ "modernc.org/sqlite"
)

type DB struct {
	*sql.DB
	Driver string // "sqlite" or "postgres"
}

// Open opens the database and applies pending migrations.
func Open(driver, dsn string) (*DB, error) {
	var (
		sdb *sql.DB
		err error
	)
	switch driver {
	case "sqlite", "":
		driver = "sqlite"
		sep := "?"
		if strings.Contains(dsn, "?") {
			sep = "&"
		}
		if !strings.HasPrefix(dsn, "file:") {
			dsn = "file:" + dsn
		}
		dsn += sep + "_pragma=busy_timeout(10000)&_pragma=journal_mode(WAL)&_pragma=foreign_keys(1)" +
			"&_pragma=synchronous(NORMAL)&_pragma=secure_delete(1)&_txlock=immediate"
		sdb, err = sql.Open("sqlite", dsn)
	case "postgres":
		sdb, err = sql.Open("pgx", dsn)
	default:
		return nil, fmt.Errorf("unsupported database driver %q", driver)
	}
	if err != nil {
		return nil, err
	}
	d := &DB{DB: sdb, Driver: driver}
	if err := sdb.Ping(); err != nil {
		return nil, fmt.Errorf("database connection: %w", err)
	}
	if err := d.migrate(); err != nil {
		return nil, fmt.Errorf("migrate: %w", err)
	}
	return d, nil
}

// Rebind converts "?" placeholders to the dialect's form.
func (d *DB) Rebind(q string) string {
	if d.Driver != "postgres" {
		return q
	}
	var b strings.Builder
	n := 0
	for i := 0; i < len(q); i++ {
		if q[i] == '?' {
			n++
			b.WriteByte('$')
			b.WriteString(strconv.Itoa(n))
		} else {
			b.WriteByte(q[i])
		}
	}
	return b.String()
}

// Q is the query interface shared by DB and Tx.
type Q interface {
	Exec(ctx context.Context, q string, args ...any) error
	Row(ctx context.Context, q string, args ...any) *sql.Row
	Each(ctx context.Context, q string, args []any, fn func(*sql.Rows) error) error
}

type raw interface {
	ExecContext(ctx context.Context, q string, args ...any) (sql.Result, error)
	QueryContext(ctx context.Context, q string, args ...any) (*sql.Rows, error)
	QueryRowContext(ctx context.Context, q string, args ...any) *sql.Row
}

func each(ctx context.Context, r raw, q string, args []any, fn func(*sql.Rows) error) error {
	rows, err := r.QueryContext(ctx, q, args...)
	if err != nil {
		return err
	}
	defer rows.Close()
	for rows.Next() {
		if err := fn(rows); err != nil {
			return err
		}
	}
	return rows.Err()
}

func (d *DB) Exec(ctx context.Context, q string, args ...any) error {
	_, err := d.DB.ExecContext(ctx, d.Rebind(q), args...)
	return err
}

func (d *DB) Row(ctx context.Context, q string, args ...any) *sql.Row {
	return d.DB.QueryRowContext(ctx, d.Rebind(q), args...)
}

func (d *DB) Each(ctx context.Context, q string, args []any, fn func(*sql.Rows) error) error {
	return each(ctx, d.DB, d.Rebind(q), args, fn)
}

// Tx is a transaction with the same helper methods as DB.
type Tx struct {
	tx *sql.Tx
	d  *DB
}

func (t *Tx) Exec(ctx context.Context, q string, args ...any) error {
	_, err := t.tx.ExecContext(ctx, t.d.Rebind(q), args...)
	return err
}

func (t *Tx) Row(ctx context.Context, q string, args ...any) *sql.Row {
	return t.tx.QueryRowContext(ctx, t.d.Rebind(q), args...)
}

func (t *Tx) Each(ctx context.Context, q string, args []any, fn func(*sql.Rows) error) error {
	return each(ctx, t.tx, t.d.Rebind(q), args, fn)
}

// InTx runs fn in a transaction, rolling back on error.
func (d *DB) InTx(ctx context.Context, fn func(tx *Tx) error) error {
	tx, err := d.DB.BeginTx(ctx, nil)
	if err != nil {
		return err
	}
	if err := fn(&Tx{tx: tx, d: d}); err != nil {
		_ = tx.Rollback()
		return err
	}
	return tx.Commit()
}

func (d *DB) migrate() error {
	ctx := context.Background()
	if err := d.Exec(ctx, `CREATE TABLE IF NOT EXISTS schema_migrations (version INTEGER PRIMARY KEY, applied_at BIGINT NOT NULL)`); err != nil {
		return err
	}
	var current int
	if err := d.Row(ctx, `SELECT COALESCE(MAX(version),0) FROM schema_migrations`).Scan(&current); err != nil {
		return err
	}
	for i := current; i < len(migrations); i++ {
		err := d.InTx(ctx, func(tx *Tx) error {
			for _, stmt := range strings.Split(migrations[i], ";\n") {
				if strings.TrimSpace(stmt) == "" {
					continue
				}
				if err := tx.Exec(ctx, stmt); err != nil {
					return fmt.Errorf("migration %d: %w\n%s", i+1, err, stmt)
				}
			}
			return tx.Exec(ctx, `INSERT INTO schema_migrations (version, applied_at) VALUES (?, ?)`, i+1, nowUnix())
		})
		if err != nil {
			return err
		}
	}
	return nil
}

// SchemaVersion returns the number of migrations known to this binary.
func SchemaVersion() int { return len(migrations) }
